import {mountEditorSearch} from './editor-search.js';
import {normalizePriorityTable,activeCombatEffects} from './combat-mechanics.js';
import {cardComposerMarkup,readCardComposer,mountCardComposer} from './card-builder.js';
import {abilityCostText} from './card-abilities.js';
import {canPayAbility} from './card-runtime.js';
import {skillPlan,createBoardModel,boardMarkup,partyMarkup,statusMarkup,mountBoardPreview} from './battle-ui.js';
import {altitude,bodyRadius,flightLimit,engagedBy,withdrawalCost} from './tactics.js';
import {ROSTER,CARD_BY_ID,SKILL_BANK,NP_BANK,SKILL_BY_BANK,NP_BY_BANK,STOCK_CARDS,TRAITS,MASTER_SKILLS,DEFAULT_MASTER,createCustomServant,createMasterCard,traitAudit,traitPrice,CATALOGUE_MANIFEST,CLASS_IDS,classPackage} from './roster.js';
import {SERVANTS,BY_ID,SIZE,LANDMARKS,terrain,RULES,REGIONS,REGION_BY_ID,TIME_SLOTS,adjacentRegions,WORLD_EDGES,LIBRARY_RULES} from './data.js';
import {createRoom,startGame,action,tick,activeUnit,dailyReady,dailyCanResolve,reachable,dist,sight,battleUnits,manaCost,publicState,decisionUnit,chargeCells,availableMana,counterOptions,canUseDefense} from './engine.js';
const $=s=>document.querySelector(s),app=$('#app'),modal=$('#modal');let state=null,credentials=null,demo=false,selected='saber',mode=null,inspected=null,busy=false,polling=false,tab='battle',lastDemo=0,mapView=null,selectedRegion=null,localGame=null,controlTarget=null,controlCommand=null,actorSelection=null,lastDecisionId=null,rosterFilter="",rosterClass="all";
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={saber:'M12 3v13m-4-4 4 4 4-4M7 17h10m-5 0v5M12 3l-3 4 3 2 3-2z',archer:'M6 3q18 9 0 18M6 3v18M3 12h18m-4-4 4 4-4 4',lancer:'M4 21 18 7m-3-4 6 0 0 6-6-6M7 14l3 3',rider:'M5 16h13l2-7-6-4-4 4 1 4-6-2zM7 16l-2 5m12-5 2 5M14 5V2',caster:'M3 5q5-2 9 1 4-3 9-1v15q-5-2-9 1-4-3-9-1zM12 6v15m-6-11h3m6 0h3m-12 4h3m6 0h3',assassin:'M4 17 12 3l8 14-8 5zM7 14l3 1m7-1-3 1M12 17v2',berserker:'M5 3l4 6-3 4 6 9 6-9-3-4 4-6-7 4zM9 13h1m4 0h1'};
const icon=(id,cls='')=>{id=CARD_BY_ID[id]?.classId||id;if(id==='master')id='caster';return `<svg class="sigil ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.1" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[id]}"/></svg>`;};
const crest='<img class="crest" src="/crest.svg" alt="">';
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('show');clearTimeout(toast.timer);toast.timer=setTimeout(()=>$('#toast').classList.remove('show'),3500);}
function openModal(html){modal.innerHTML=`<button class="close" data-do="close" aria-label="关闭">×</button>${html}`;modal.showModal();}
function rules(){openModal(`<div class="eyebrow">FIELD MANUAL · v0.6.1</div><h2>圣杯战争 · 作战手册</h2><p class="muted">《极简杯》框架 × 第四次圣杯战争 · 网页战棋改编</p>${state&&state.host===state.me?'<button class="secondary" data-do="priorityOpen">配置规则优先级</button>':''}<div class="rules">${RULES.map(([h,p],i)=>`<section><span class="rule-no">${String(i+1).padStart(2,'0')}</span><div><h3>${h}</h3><p>${p}</p></div></section>`).join('')}</div>`);}
/*CARD*/
function header(){return `<header><a class="brand" href="/">${crest}<div>冬木<span>F U Y U K I · G R A I L W A R</span></div></a><nav><button class="nav-button ${tab==='battle'?'on':''}" data-do="battle">${state?'圣杯战场':'战争大厅'}</button><button class="nav-button" data-do="archive">英灵档案 <span>369</span></button><button class="nav-button" data-do="rules">规则手册 ↗</button></nav><div class="header-meta"><i></i>${demo?'本地演习':state?'灵脉已连接':'第四次圣杯战争'}<span> FUYUKI · 1994</span></div></header>`;}
function landing(){const s=BY_ID[selected];app.innerHTML=`${header()}<main class="landing"><div class="intro"><div class="eyebrow"><span class="line"></span> THE FOURTH HOLY GRAIL WAR</div><h1>七骑降临。<br>唯有一人，<em>抵达圣杯。</em></h1><p class="intro-copy">夜幕下的冬木市，七位英灵再度回应召唤。<br>选择你的从者，在大地图筹划，在战斗地图交锋。</p><div class="tags"><span>◷ 每日四时段</span><span>♟ 双层地图</span><span>◇ 七人联网</span></div><div class="entry-form"><label for="playerName">御主代号</label><input id="playerName" maxlength="20" placeholder="输入你的名字" value="${esc(localStorage.getItem('grail-name')||'')}" autocomplete="nickname"><div class="entry-actions"><button class="primary" data-do="create">缔结契约 · 创建房间 <span>↗</span></button><button class="secondary" data-do="joinDialog">加入战争</button></div><button class="text-button" data-do="demo">先试一局 · 与六位 AI 演习 <span>→</span></button></div><div class="landing-note"><span>01 — 07</span> 基于《极简杯》规则的战棋改编 · 测试版 v0.6.1</div></div><div class="summon-showcase" style="--accent:${s.color}"><div class="summon-top"><span>SPIRIT ORIGIN / 0${SERVANTS.indexOf(s)+1}</span><span class="small-tag">${s.class}</span></div><div class="magic-circle"><div class="orbit o1"></div><div class="orbit o2"></div><div class="orbit o3"></div><div class="diamond"></div><span class="rune r1">✦</span><span class="rune r2">✧</span><span class="rune r3">✦</span>${icon(s.id,'hero-icon')}<span class="seal-label">SERVANT SUMMONING SYSTEM</span></div><div class="hero-info"><span class="eyebrow">${s.title} / ${s.class}</span><h2>${s.name}</h2><p>“${s.quote}”</p><button class="text-button" data-do="card" data-id="${s.id}">查看从者卡 <span>↗</span></button></div><div class="summon-bottom"><span>契约尚未缔结</span><span>✦ AWAITING MASTER</span></div></div><section class="servant-strip"><div class="strip-label"><span>SEVEN SERVANTS</span><h3>选择回应你的英灵</h3></div>${SERVANTS.map(s=>`<button class="servant-pick ${s.id===selected?'selected':''}" style="--accent:${s.color}" data-do="preview" data-id="${s.id}">${icon(s.id)}<span>${s.class}</span><b>${s.name}</b></button>`).join('')}</section></main><footer><span>F A T E / F U Y U K I</span><span>七位御主，一座冬木。<button data-do="rules">阅读改编说明 ↗</button></span></footer>`;}
function getName(){const value=($('#playerName')?.value||localStorage.getItem('grail-name')||'御主').trim()||'御主';localStorage.setItem('grail-name',value);return value;}
async function api(path,body,auth=true){const res=await fetch(path,{method:body?'POST':'GET',headers:{'content-type':'application/json',...(auth&&credentials?{authorization:'Bearer '+credentials.token}:{})},...(body?{body:JSON.stringify(body)}:{})});const out=await res.json();if(!res.ok)throw Error(out.error||'连接失败');return out;}
function storeCredentials(c){credentials=c;localStorage.setItem('grail-session',JSON.stringify(c));history.replaceState(null,'','?room='+c.code);}
async function create(){busy=true;try{const out=await api('/api/rooms',{name:getName()},false);storeCredentials({code:out.state.code,token:out.token});state=out.state;render();}catch(e){toast(e.message);}finally{busy=false;}}
async function join(code){try{const out=await api('/api/rooms/'+code.trim().toUpperCase()+'/join',{name:$('#joinName').value.trim()||'御主'},false);storeCredentials({code:out.state.code,token:out.token});state=out.state;modal.close();render();}catch(e){toast(e.message);}}
function joinDialog(code=''){openModal(`<div class="eyebrow">JOIN THE WAR</div><h2>回应圣杯的召唤</h2><p class="muted">输入好友分享的六位房间码，加入冬木战场。</p><form id="joinForm"><label for="joinName">御主代号</label><input id="joinName" maxlength="20" value="${esc(getName())}" required><label for="roomCode">房间码</label><input id="roomCode" maxlength="6" minlength="6" pattern="[A-Za-z0-9]{6}" placeholder="例如 A3F9C2" value="${esc(code)}" required><button class="primary" type="submit">加入房间 →</button></form>`);}
function enterDemo(){seenContestIds.clear();demo=true;credentials=null;localGame=createRoom('演习',getName(),'demo');localGame.host=localGame.players[0].id;state=publicState(localGame,'demo');mode=null;actorSelection=null;render();toast('本地演习：先占职阶、选择或自建从者，准备后由AI补齐其他席位。');}
let actionSending=false;
async function send(body,endpoint='action'){if(!state||actionSending)return false;actionSending=true;if(endpoint==='action'&&!body.actorId){const chooser=decisionUnit(state);body={...body,actorId:body.type==='respond'&&chooser?.owner===state.me?chooser.id:myUnit()?.id};}const oldPhase=state.phase;try{if(demo){if(endpoint==='lobby')localLobby(body);else action(localGame,body.actorId||state.me,body);state=publicState(localGame,'demo');if(state.phase!==oldPhase){mapView=null;mode=null;}render();}else{const code=credentials.code;state=await api(`/api/rooms/${code}/${endpoint}`,{...body,revision:state.revision});if(state.phase!==oldPhase){mapView=null;mode=null;}render();}return true;}catch(e){toast(e.message);if(!demo)await poll();return false;}finally{actionSending=false;}}
/*LOBBY*/
function bar(value,max,color){return `<div class="bar" style="--bar:${color}"><i style="width:${Math.max(0,value/max*100)}%"></i></div>`;}
function terrainDecoration(){return `<svg class="map-decor" viewBox="0 0 650 650" aria-hidden="true"><defs><pattern id="streets" width="100" height="100" patternUnits="userSpaceOnUse"><path d="M0 26h100M28 0v100M64 0v100M0 64h100" stroke="#728a7c" stroke-width="1" opacity=".22"/><path d="M34 32h24v26H34zM70 32h22v26H70zM34 70h24v22H34zM4 32h18v26H4zM4 70h18v22H4z" fill="#718578" opacity=".13"/></pattern></defs><rect width="650" height="650" fill="url(#streets)"/><path d="M312 0c-15 80 25 120 10 195s-20 90-10 150 20 95 10 150-10 115-8 155" stroke="#395d65" stroke-width="55" fill="none"/><path d="M310 0c-15 80 25 120 10 195s-20 90-10 150 20 95 10 150-10 115-8 155" stroke="#82b5bb" stroke-opacity=".13" stroke-width="1" stroke-dasharray="5 8" fill="none"/><path d="M0 175h650M0 325h650M0 475h650" stroke="#bac3a3" stroke-width="9" opacity=".12"/><path d="M0 175h650M0 325h650M0 475h650" stroke="#a6b3a0" stroke-width="1" opacity=".4"/><circle cx="475" cy="475" r="58" fill="#637b61" opacity=".12"/><text x="335" y="560" fill="#a2babe" opacity=".3" font-size="11" letter-spacing="5" transform="rotate(-90 335 560)">MIYAMA RIVER</text><text x="400" y="70" fill="#c3c8a7" opacity=".2" font-size="14" letter-spacing="5">SHINTO</text><text x="70" y="590" fill="#c3c8a7" opacity=".2" font-size="14" letter-spacing="5">MIYAMA</text></svg>`;}
function pieceName(u){return ({saber:'剑',archer:'弓',lancer:'枪',rider:'骑',caster:'术',assassin:'杀',berserker:'狂'}[u.servant]||'从')+(u.kind==='master'?'御':'');}
function battlefield(){
 const current=activeUnit(state)||myUnit(),me=myUnit(),isMine=current?.id===me.id&&state.phase==='battle',focus=state.units.find(u=>u.id===inspected)||me;
 const model=createBoardModel(state,me,mode,{target:controlTarget,command:controlCommand});
 const logRows=[...state.log].reverse().slice(0,60).map(l=>`<div class="log-entry ${esc(l.type)}"><span>R${String(l.round).padStart(2,'0')}</span><p>${esc(l.text)}</p></div>`).join('');
 return `<main class="war-room tactical-screen"><div class="war-title"><div><div class="eyebrow">TACTICAL FIELD / ${demo?'TRAINING':esc(state.code)}</div><h1>${REGION_BY_ID[state.battle.region].name}<span class="version">区域战斗</span></h1><p class="calendar-inline">第 ${state.day} 天 · ${TIME_SLOTS[state.timeSlot]} · ${state.battle.participants.length} 位参战 · 日常时间暂停</p></div><div class="war-controls"><button class="secondary compact" data-do="copy">${demo?'本地演习':esc(state.code)+' ⧉'}</button><button class="secondary compact" data-do="worldView">大地图</button><button class="nav-button" data-do="leave">退出</button></div></div><div class="turn-track"><div class="round-counter"><small>战斗轮次</small><strong>${String(state.round).padStart(2,'0')}</strong></div><div class="turn-units">${state.order.map(id=>{const u=state.units.find(u=>u.id===id),c=viewDef(u);return `<button class="turn-unit ${u.id===current?.id?'now':''} ${!u.alive?'dead':''} ${u.id===me.id?'my-turn-unit':''}" data-do="inspect" data-id="${u.id}" style="--accent:${c.color}">${icon(u.kind==='master'?'master':u.servant)}<div><small>${u.kind==='master'?'御主':c.class}${u.owner===state.me?' · 我方':''}</small><b>${esc(c.name)}</b></div></button>`;}).join('')}</div><span id="countdown">--:--</span></div>${grailPanel()}<div class="battle-grid">${partyMarkup(state,me.id,icon)}<section class="map-panel sheet-board"><div class="map-header"><span><i class="live-dot"></i>${isMine?'我方回合':esc(viewDef(current).name)+' 行动中'}</span><small>${SIZE} × ${SIZE} / A–T · 1–20</small></div><div class="sheet-toolbar"><div><button class="${model.effectiveMode==='move'?'chosen':''}" data-do="mode" data-id="move" ${!model.canAct||me.channel?'disabled':''}>移动</button><button class="${mode==='backstep'?'chosen':''}" data-do="mode" data-id="backstep" ${!isMine||state.pendingAttack||me.channel?'disabled':''}>后撤</button><button class="${mode==='attack'?'chosen':''}" data-do="mode" data-id="attack" ${!isMine||state.pendingAttack||me.channel?'disabled':''}>普攻</button><button data-do="cancelAim" ${!mode?'disabled':''}>取消 <kbd>ESC</kbd></button></div><p data-aim-hint role="status">${esc(model.hint)}</p></div>${boardMarkup(state,me,model,icon)}<div class="board-legend"><span><i class="legend-move"></i>可移动</span><span><i class="legend-attack"></i>攻击射程</span><span><i class="legend-skill"></i>实际影响范围</span><span>实线：合法目标 · ×：不可释放</span></div></section><aside class="battle-right"><section class="action-panel panel">${responsePanel()}${unitPanel(focus,me,isMine)}</section><section class="battle-log panel"><div class="panel-title"><span>战斗记录</span><button class="text-button" data-do="export">导出 ↓</button></div><div class="log-entries" data-preserve-scroll="log">${logRows}</div><details class="battle-dice"><summary>我的属性对抗记录</summary>${diceHistoryPanel()||'<p class="tiny muted">暂无对抗记录</p>'}</details></section></aside></div></main>`;
}
/*UNITPANEL*/
function render(){document.body.dataset.slot=String(state?.timeSlot??3);if(!state){landing();return;}const decision=decisionUnit(state);if(decision?.id!==lastDecisionId){lastDecisionId=decision?.id;if((decision?.owner||decision?.id)===state.me){actorSelection=decision.id;inspected=null;cancelBattleAim(false);}}const combat=state.battle&&!state.battle.spectator&&(mapView==='battle'||mapView!=='world'&&state.phase!=='daily');const scrolls=Object.fromEntries([...app.querySelectorAll('[data-preserve-scroll]')].map(el=>[el.dataset.preserveScroll,el.scrollTop]));app.innerHTML=header()+(state.phase==='lobby'?lobby():combat?battlefield():worldMap())+(state.phase==='finished'?resultOverlay():'');for(const el of app.querySelectorAll('[data-preserve-scroll]'))el.scrollTop=scrolls[el.dataset.preserveScroll]||0;if(combat)mountBoardPreview(app,createBoardModel(state,myUnit(),mode,{target:controlTarget,command:controlCommand}));countdown();playBattleFX();playContestDice();}
function countdown(){const el=$('#countdown');if(el&&['daily','battle'].includes(state?.phase)){const sec=Math.max(0,Math.ceil((state.deadline-Date.now())/1000));el.textContent=String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0');el.classList.toggle('urgent',sec<20);}}
async function poll(){if(demo||!credentials||polling)return;polling=true;try{const next=await api('/api/rooms/'+credentials.code);const changed=next.revision!==state?.revision;if(next.phase!==state?.phase){mapView=null;mode=null;}state=next;if(changed){if(activeUnit(state)?.id!==myUnit()?.id&&!(mode==='releaseNP'&&myUnit()?.channel?.instant))cancelBattleAim(false);render();}}catch(e){if(!navigator.onLine)toast('网络已断开，恢复连接后会自动重连。');}finally{polling=false;}}
async function copyInvite(){if(demo){toast('这是本地 AI 演习，创建联网房间后即可邀请好友。');return;}const url=location.origin+'/?room='+state.code;try{await navigator.clipboard.writeText(url);toast('邀请链接已复制，分享给其他御主即可加入。');}catch{openModal(`<h2>邀请御主</h2><p>房间码：${state.code}</p><input readonly value="${esc(url)}" onclick="this.select()">`);}}
app.addEventListener('change',e=>{if(e.target.classList.contains('spirit-select')){send({type:'spirit',servant:e.target.dataset.servant,spirit:e.target.value},'lobby');return;}if(e.target.id==='autoMorale')send({type:'autoMorale',enabled:e.target.checked});});
document.addEventListener('submit',e=>{if(e.target.id==='joinForm'){e.preventDefault();join($('#roomCode').value);}});
document.addEventListener('click',async e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;const id=b.dataset.id;switch(b.dataset.do){
case 'close':modal.close();break;case 'rules':rules();break;case 'card':card(CARD_BY_ID[id]||state?.units?.find(u=>u.id===id)?.card||state?.players?.map(playerCard).find(c=>c?.id===id)||BY_ID[id]);break;case 'preview':getName();selected=id;landing();break;
case 'archive':openArchive();break;case 'battle':if(modal.open)modal.close();break;case 'create':if(!busy)create();break;case 'joinDialog':joinDialog();break;case 'demo':enterDemo();break;
case 'copy':copyInvite();break;case 'select':send({type:'claim',servant:id},'lobby');break;case 'roster':openRoster();break;case 'pickCard':modal.close();send({type:'card',cardId:id},'lobby');break;case 'builder':openBuilder('servant');break;case 'masterBuilder':openBuilder('master');break;case 'saveBuilder':saveBuilder(b.dataset.kind);break;case 'releaseClass':send({type:'releaseClass'},'lobby');break;case 'ready':send({type:'ready',ready:!state.players.find(p=>p.id===state.me).ready},'lobby');break;case 'start':send({type:'start',fill:state.players.length<7},'lobby');break;
case 'inspect':{const target=state?.units.find(u=>u.id===id);if(target&&(target.owner||target.id)===state.me)selectBattleActor(id);else{cancelBattleAim(false);inspected=id;render();}break;}
case 'mode':cancelBattleAim(false);mode=id;inspected=myUnit()?.id;render();break;
case 'cancelAim':cancelBattleAim();break;
case 'cell':await clickBattleCell(+b.dataset.x,+b.dataset.y);break;
case 'ability':await activateBattleSkill(id);break;
case 'confirmMasterSkill':{const extra={};if($('#restartSkill'))extra.targetSkill=$('#restartSkill').value;if($('#emergencyResource'))extra.resource=$('#emergencyResource').value;modal.close();send({type:'masterSkill',skill:id,...extra});break;}case 'healServant':send({type:'masterTrait'});break;case 'switchActor':selectBattleActor(id);break;case 'channel':send({type:'channel'});break;case 'cancelChannel':send({type:'cancelChannel'});break;case 'grailPickup':send({type:'grailPickup'});break;case 'grailDrop':send({type:'grailDrop',actorId:state.grail.holderId});break;case 'grailRitual':send({type:'grailRitual'});break;case 'mapImage':$('#mapImageInput').click();break;case 'resetMapImage':localStorage.removeItem('grail-map-image');render();break;case 'sweep':cancelBattleAim(false);mode='sweep';render();break;case 'supply':supplyDialog();break;case 'confirmSupply':{const amount=+$('#supplyAmount').value;modal.close();send({type:'supply',amount});break;}case 'respondAttribute':submitResponse({attribute:+id});break;case 'respondModifier':submitResponse({useEternal:id==='yes'});break;case 'respondInstinct':submitResponse({instinctChoice:id});break;case 'respondContinue':submitResponse({});break;case 'instantResist':send({type:'skill',skill:'resist'});break;case 'confirmLibrary':confirmLibrary(id);break;case 'controlCommand':modal.close();controlCommand=id;controlTarget=null;mode='sacrifice';inspected=myUnit()?.id;render();toast('步骤1/2：选择受控单位，再选择其动作目标。');break;case 'worldView':mapView='world';mode=null;render();break;case 'battleView':mapView='battle';mode=null;render();break;case 'region':selectedRegion=id;render();break;case 'dailyMove':send({type:'dailyMove',region:id});break;case 'dailyEat':recoveryDialog('dailyEat');break;case 'dailySleep':recoveryDialog('dailySleep');break;case 'dailyRecover':modal.close();send({type:b.dataset.kind,resource:id});break;case 'dailyLey':send({type:'dailyLey'});break;case 'dailyEnd':send({type:'dailyEnd'});break;case 'dailyResolve':send({type:'dailyResolve'});break;case 'engage':encounterDialog();break;case 'confirmEngage':modal.close();mapView=null;send({type:'engage',target:id});break;case 'confirmAmbush':modal.close();mapView=null;send({type:'dailyAmbush',target:id});break;case 'retreatChoice':modal.close();send({type:'retreat',region:id});break;case 'confirmSkill':modal.close();send({type:'skill',skill:id});break;case 'retreat':retreatDialog();break;case 'end':mode=null;send({type:'end'});break;
case 'seal':openSealDialog();break;case 'sealChoice':chooseSeal(id);break;case 'confirmSeal':confirmSeal(id);break;
case 'leave':openModal(`<h2>${demo?'结束本次演习？':'返回战争大厅？'}</h2><p class="muted">${demo?'本地演习进度将结束。':'联网身份会保留，可通过“重连房间”回到当前战局。回合计时将继续。'}</p><button class="primary" data-do="confirmLeave">确认返回</button><button class="secondary" data-do="close">继续战争</button>`);break;
case 'confirmLeave':modal.close();state=null;demo=false;credentials=null;mode=null;inspected=null;mapView=null;selectedRegion=null,localGame=null,controlTarget=null,controlCommand=null,actorSelection=null,lastDecisionId=null,rosterFilter="",rosterClass="all";history.replaceState(null,'','/');render();if(localStorage.getItem('grail-session')){const form=$('.entry-form');form.insertAdjacentHTML('beforeend','<button class="text-button" data-do="reconnect">重连上次房间 →</button>');}break;
case 'reconnect':credentials=JSON.parse(localStorage.getItem('grail-session')||'null');if(credentials){await poll();render();}break;
case 'review':$('.result-overlay').remove();break;case 'export':{const a=document.createElement('a');const url=URL.createObjectURL(new Blob([state.log.map(l=>`[第${l.day||1}天 ${TIME_SLOTS[l.timeSlot||0]}${l.round?' 战斗R'+l.round:''}] ${l.text}`).join('\n')],{type:'text/plain;charset=utf-8'}));a.href=url;a.download=`冬木战报-${state.code}.txt`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);break;}
}});
modal.addEventListener('click',e=>{if(e.target===modal&&e.offsetX<0)modal.close();});
setInterval(()=>{countdown();if(demo&&['daily','battle'].includes(state?.phase)&&Date.now()-lastDemo>1100){lastDemo=Date.now();const oldPhase=state.phase;if(tick(localGame)){state=publicState(localGame,'demo');if(oldPhase!==state.phase)mapView=null;if(activeUnit(state)?.id!==myUnit()?.id&&!(mode==='releaseNP'&&myUnit()?.channel?.instant))cancelBattleAim(false);render();}}},500);
setInterval(poll,1500);
render();
const requested=new URLSearchParams(location.search).get('room')?.toUpperCase();let saved=null;try{saved=JSON.parse(localStorage.getItem('grail-session')||'null');}catch{}
if(saved&&(!requested||requested===saved.code)){credentials=saved;api('/api/rooms/'+saved.code).then(g=>{state=g;render();}).catch(()=>{credentials=null;if(requested)joinDialog(requested);});}else if(requested&&/^[A-Z0-9]{6}$/.test(requested))joinDialog(requested);

function recoveryDialog(kind){const sleep=kind==='dailySleep';openModal(`<div class="eyebrow">DAILY ACTION · ${sleep?3:1} POINT${sleep?'S':''}</div><h2>${sleep?'休眠':'进食'} · 日常恢复</h2><p>消耗 ${sleep?3:1} 点日常行动，选择恢复 ${sleep?'4d10':'1d10'} 生命或魔力。不会支付或增加战斗行动点。</p><div class="seal-options"><button class="secondary" data-do="dailyRecover" data-kind="${kind}" data-id="hp">恢复生命 HP</button><button class="secondary" data-do="dailyRecover" data-kind="${kind}" data-id="mp">恢复魔力 MP</button></div>`);}
function retreatDialog(){const u=myUnit();if(u.x!==0&&u.y!==0&&u.x!==SIZE-1&&u.y!==SIZE-1){toast('先移动到战斗地图最外围，再支付 1 战斗行动点撤退。');return;}openModal(`<div class="eyebrow">WITHDRAW · 1 BATTLE AP</div><h2>撤退到相邻区域</h2><p>消耗 1 战斗行动点并失去 1 士气，不追加日常费用。请选择目的地：</p><div class="seal-options">${adjacentRegions(state.battle.region).map(r=>`<button class="secondary" data-do="retreatChoice" data-id="${r.id}">${r.name}</button>`).join('')}</div>`);}
function calendar(){return `<div class="calendar"><div class="day-label"><small>HOLY GRAIL WAR</small><b>第 ${state.day} 天</b></div><div class="time-slots">${TIME_SLOTS.map((slot,i)=>`<div class="time-slot ${i===state.timeSlot?'current':''} ${i<state.timeSlot?'passed':''}"><small>0${i+1} / 04</small><b>${i<2?'☀':'☾'} ${slot}</b></div>`).join('')}</div><div class="calendar-rule">每天 4 时间回合<br><b>3 点 · 每点同步提交一次</b></div></div>`;}
function chronology(){return `<section class="battle-log panel"><div class="panel-title"><span>圣杯观测记录 <small>DAILY / BATTLE CHRONICLE</small></span><button class="text-button" data-do="export">导出战报 ↓</button></div><div class="log-entries">${[...state.log].reverse().slice(0,35).map(l=>`<div class="log-entry ${l.type}"><span>D${l.day||state.day}·${(l.timeSlot||0)+1}${l.round?' / B'+l.round:''}</span><p>${esc(l.text)}</p></div>`).join('')}</div></section>`;}
/*WORLDMAP*/
function resultOverlay(){return `<div class="result-overlay"><div class="result"><div class="eyebrow">THE WAR HAS ENDED</div>${state.winner?icon(state.units.find(u=>u.id===state.winner).servant,'large'):crest}<h2>${state.winner?BY_ID[state.units.find(u=>u.id===state.winner).servant].name+' · 获得圣杯':'圣杯沉寂，战争平局'}</h2><p>第 ${state.day} 天 · ${TIME_SLOTS[state.timeSlot]} · ${demo?'演习结束':'契约履行完毕'}</p><button class="primary" data-do="review">查看最终战报</button><button class="secondary" data-do="leave">回到战争大厅</button></div></div>`;}

function stat(v){return v===null||v===undefined?'?':v;}
function worldRoads(){return `<svg class="world-roads" viewBox="0 0 100 100" preserveAspectRatio="none" aria-label="十三节点树形道路">${WORLD_EDGES.map(([a,b])=>`<line x1="${REGION_BY_ID[a].px}" y1="${REGION_BY_ID[a].py}" x2="${REGION_BY_ID[b].px}" y2="${REGION_BY_ID[b].py}"/>`).join('')}</svg>`;}
function encounterDialog(){const me=myUnit(),targets=state.units.filter(u=>(u.owner||u.id)!==state.me&&u.alive&&u.region===me.region);openModal(`<div class="eyebrow">DETECTED CONTACTS</div><h2>选择已经发现的目标</h2><p>发起战斗不扣日常点。战斗结束后，每位实际参战单位的下一次日常行动扣 1 点并跳过；尚未执行的已提交行动将被替代，无可用点时顺延。单方面发现时可选择偷袭；偷袭会先进行敏捷对抗，并按规则处理部位攻击和后续应对，随后暴露自身。</p><div class="encounter-targets">${targets.map(u=>`<section><b>${viewDef(u).name}</b><button class="secondary" data-do="confirmEngage" data-id="${u.id}">公开挑战</button>${state.ambushTargets?.includes(u.id)?`<button class="primary" data-do="confirmAmbush" data-id="${u.id}">单方面发现 · 偷袭</button>`:'<small>未满足偷袭条件</small>'}</section>`).join('')}</div>`);}
function libraryDialog(k){
 const u=myUnit(),daily=state.phase==='daily';if(k.libraryKey==='pollution'){openModal(`<div class="eyebrow">${k.source}</div><h2>${k.name}</h2><p>${k.desc}</p><p>选择要强制的动作，再在棋盘指定受控从者及其动作目标。</p><div class="seal-options"><button class="secondary" data-do="controlCommand" data-id="attack">令其攻击</button><button class="secondary" data-do="controlCommand" data-id="move">令其移动</button><button class="secondary" data-do="controlCommand" data-id="charge">令其冲锋</button></div>`);return;}
 let options='';if(k.id==='burst')options=`<label for="burstX">x（1～${['E','D','C','B','A','EX'].indexOf(k.rank)+3}，每点消耗5 MP）</label><input id="burstX" type="number" min="1" max="${['E','D','C','B','A','EX'].indexOf(k.rank)+3}" value="1"><label for="libraryChoice">选择一种效果</label><select id="libraryChoice"><option value="normal">通常攻击 +2x，持续3战斗轮次</option><option value="reduction">全类型减伤 +x，持续3战斗轮次</option><option value="special">下次特殊攻击 +4x</option><option value="armor">通常攻击减伤 +4x，至下一轮结束</option></select>`;
 if(k.id==='charisma'){const max=['E','D','C','B','A','EX'].indexOf(k.rank.replace(/\+/g,''))+1;options=`<label for="libraryTier">灵活运用等级</label><select id="libraryTier">${Array.from({length:max},(_,i)=>`<option value="${i+1}" ${i+1===max?'selected':''}>${['E','D','C','B','A','EX'][i]} · ${(i+1)*10*(state.day>7?2:1)} MP · 对抗 +${i+1}</option>`).join('')}</select>`;}
 openModal(`<div class="eyebrow">SKILL DATABASE · ${daily?'日常阶段':'战斗阶段'}</div><h2>${k.name} ${k.rank}</h2><p>${k.desc}</p><p class="muted">${daily?k.dailyAP||1:k.battleAP} ${daily?'日常':'战斗'}行动点 · 当前基础消耗 ${manaCost(state,k,u)} MP${k.id==='dragon'?' · 另需1士气':''}</p>${options}<details class="library-source"><summary>查看所提供技能库的原文</summary><pre>${esc(LIBRARY_RULES[k.libraryKey].text)}</pre></details><button class="primary" data-do="confirmLibrary" data-id="${k.id}">确认使用 →</button>`);
}
function confirmLibrary(id){const extra={};if(id==='burst'){extra.xValue=+$('#burstX').value;extra.choice=$('#libraryChoice').value;}if(id==='charisma')extra.tier=+$('#libraryTier').value;modal.close();send({type:'skill',skill:id,...extra});}
function submitResponse(extra){const opts={};if($('#protectionChoice'))opts.protectionId=$('#protectionChoice').value;if($('#revivalChoice'))opts.revivalId=$('#revivalChoice').value;if($('#useInstinct')?.checked){opts.instinct=true;opts.instinctTier=+($('#instinctTier')?.value||5);}if($('#useEternal')?.checked)opts.useEternal=true;send({type:'respond',...opts,...extra});}
function responsePanel(){const p=state.pendingAttack;if(!p)return '';const chooser=decisionUnit(state),mine=(chooser?.owner||chooser?.id)===state.me,a=state.units.find(u=>u.id===p.attacker),b=state.units.find(u=>u.id===p.target),defense=['defender','part','defenderReaction','moraleChoice'].includes(p.stage),mod=['attackModifier','defendModifier','sneakModifier'].includes(p.stage);
 const independent=['unrespondableReaction','hpLossReaction'].includes(p.stage);const title=independent?(p.stage==='hpLossReaction'?'生命流失：仅进行HP保护判定':'不可应对：跳过属性对抗，可独立防御')+' · 第'+(p.segment||1)+'/'+(p.segments||1)+'段':p.stage==='moraleChoice'?'两次对抗结束：是否用士气挽回一次失败应对':p.stage==='part'?'偷袭：防守方选择部位攻击前置对抗属性':p.stage==='instinctChoice'?'直感掷出6：选择对宝具的应对收益':p.stage==='defenderReaction'?'对方气息遮蔽改变选属性权：选择防御反应':mod?'无穷武炼：是否取消本次双方全部加值':p.stage==='defender'?'第一道对抗：防守方选择属性':p.stage==='overrideDefender'?'气息遮蔽：攻击方选择第一道对抗属性':'第二道对抗：攻击方选择属性';
 const self=mine?chooser:myUnit(),resist=viewDef(self).skills.find(k=>k.id==='resist');return `<section class="response-panel ${mine?'your-response':''}" aria-live="polite"><div class="eyebrow">ATTRIBUTE CONTEST · ${esc(p.skill.name||'通常攻击')} · 第${p.segment||1}/${p.segments||1}段</div><div class="response-heading"><h2>${title}</h2><span>${viewDef(a).name} → ${viewDef(b).name}</span></div><p class="response-formula">${independent?'本段不产生属性对抗成功或失败事件。可先使用符合时机的独立防御，再继续；生命流失不属于伤害。':'双方使用同一项被选属性，各掷「自身该属性等级数量 d6＋幸运＋技能加值」。攻击方成功 0／1／2 次 = 0%／50%／100% 最终伤害。'}</p>${p.checks.length?`<p class="check-result">已完成：${p.checks.map(c=>c.skipped?'偷袭跳过防守者应对，记攻击方成功':esc(c.text)+'；攻击方'+(c.attackerSuccess?'成功':'失败')).join('；')}</p>`:''}${state.units.some(u=>u.alive&&(u.owner||u.id)===state.me&&u.id!==b.id&&(b.owner||b.id)===state.me&&(u.assistReady||viewDef(u).traits?.aid))?`<button class="secondary" data-do="aid" data-id="${state.units.find(u=>u.alive&&(u.owner||u.id)===state.me&&u.id!==b.id&&(u.assistReady||viewDef(u).traits?.aid))?.id}">及时援护 · 10 MP</button>`:''}${mine?counterChoices(chooser)+defenseChoices(chooser)+protectionChoices(chooser):''}${!mine?`<p class="waiting-response">等待 ${viewDef(chooser).name} 操作；攻击尚未结算，不会自动替其选属性。</p>`:`<div class="response-options">${defense&&!p.skipContest&&viewDef(self).skills.some(k=>k.libraryKey==='instinct')&&!p.reaction.instinctDone?`<label><input type="checkbox" id="useInstinct" ${self.mp<10?'disabled':''}> 使用直感 <select id="instinctTier">${['E','D','C','B','A','EX'].slice(0,['E','D','C','B','A','EX'].indexOf(viewDef(self).skills.find(k=>k.libraryKey==='instinct')?.rank)+1).map((t,i)=>`<option value="${i+1}" ${i===0?'selected':''}>${t} · ${[10,12,14,16,18,20][i]*(state.day>7?2:1)} MP</option>`).join('')}</select></label>`:''}${!mod&&!p.skipContest&&viewDef(self).skills.some(k=>k.libraryKey==='eternal')&&self.eternalRemaining>0?`<label><input type="checkbox" id="useEternal"> 无穷武炼：双方取消加值（整局剩 ${self.eternalRemaining} 次）</label>`:''}${resist&&!self.battleUses?.resist?`<button class="secondary compact" data-do="instantResist">先启用对魔力 ${resist.rank} · 不占动作</button>`:''}</div><div class="attribute-choices">${independent?'<button class="primary" data-do="respondContinue">继续本段结算</button>':p.stage==='moraleChoice'?'<button class="primary" data-do="respondMorale" data-id="yes">消耗1士气，改变一次失败应对</button><button class="secondary" data-do="respondMorale" data-id="no">保留士气，结算伤害</button>':p.stage==='instinctChoice'?`<button class="primary" data-do="respondInstinct" data-id="reduction">本次减伤 +${p.reaction.instinctReduction}</button><button class="primary" data-do="respondInstinct" data-id="contest">本次对抗 +${p.reaction.instinctBonus}</button>`:mod?'<button class="primary" data-do="respondModifier" data-id="yes">发动无穷武炼</button><button class="secondary" data-do="respondModifier" data-id="no">保留次数，不发动</button>':p.stage==='defenderReaction'?'<button class="primary" data-do="respondContinue">确认反应，继续 →</button>':['筋力','耐久','敏捷','魔力','幸运'].map((name,i)=>`<button class="secondary" data-do="respondAttribute" data-id="${i}"><b>${name}</b><small>${viewDef(chooser).ranks[i]}</small></button>`).join('')}</div>`}</section>`;
}
function supplyDialog(){const u=myUnit(),m=state.units.find(v=>v.kind==='master'&&v.owner===(u.owner||u.id)),missing=viewDef(u).mp-u.mp,max=Math.min(m?.alive?m.mp:0,missing);if(max<1){toast('御主没有可供魔力，或从者魔力已满。');return;}openModal(`<div class="eyebrow">MASTER CONSENT · NO ACTION COST</div><h2>同意御主供魔</h2><p>按 1:1 将御主魔力转给从者，不消耗日常或战斗行动点。当前最多可转 ${max} 点。</p><input id="supplyAmount" type="number" min="1" max="${max}" value="${max}"><button class="primary" data-do="confirmSupply">确认同意并转入 →</button>`);}

function viewDef(u){return u?.card||BY_ID[u?.servant]||{name:'未知单位',skills:[],ranks:['E','E','E','E','E'],color:'#b7b999',class:'MASTER',hp:0,mp:0};}
function myUnit(){if(!state?.units)return null;const mine=state.units.filter(u=>(u.owner||u.id)===state.me);return mine.find(u=>u.id===actorSelection)||mine.find(u=>u.kind==='servant')||mine[0];}
function playerCard(p){return p?.customCard?createCustomServant(p.customCard,p.servant):CARD_BY_ID[p?.cardId]||null;}
function actorSwitcher(){if(!state?.units)return '';const current=activeUnit(state);return `<div class="actor-switcher"><span>我的契约方</span>${state.units.filter(u=>(u.owner||u.id)===state.me).map(u=>`<button class="${myUnit()?.id===u.id?'chosen':''}" data-do="switchActor" data-id="${u.id}" ${!u.alive?'disabled':''}>${icon(u.kind==='master'?'master':u.servant)}<span>${u.kind==='master'?'御主':'从者'} · ${esc(viewDef(u).name)}</span><small>${u.alive?`日常 ${u.dailyAP}/3${state.phase==='daily'?(state.dailySubmitted?.includes(u.id)?' · 已选动作／跳过':' · 待选动作'):current?.id===u.id?' · 行动中':''}`:'已退场'}</small></button>`).join('')}</div>`;}
function card(c){if(!c)return;openModal(`<div class="card-heading" style="--accent:${c.color}">${icon(c.classId||c.id,'large')}<div><div class="eyebrow">${c.class} · ${c.title||''}</div><h2>${esc(c.name)}</h2><p class="muted">${esc(c.bio||c.quote||'')}</p></div></div><div class="ranks">${c.ranks.map((r,i)=>`<div>${['筋力','耐久','敏捷','魔力','幸运'][i]}<b>${r}</b></div>`).join('')}</div><p class="passive">${esc(c.passive||'')}</p>${c.sourceInfo?`<p class="source-attribution">Mooncell No.${c.sourceInfo.title} · 修订 ${c.sourceInfo.revisionId}<br><a href="${esc(c.sourceInfo.url)}" target="_blank" rel="noopener">打开对应Mooncell原始页面 ↗</a><br>原始人物资料与本版战棋效果分别保存；灵格与战棋数值为游戏改编。</p>`:''}<div class="card-skills">${c.skills.map(k=>`<section><div class="skill-title"><h3>${esc(k.name)}</h3><span>${esc(k.rank)}</span></div><small>${k.np?'宝具 · ':''}${esc(k.phase||'battle')} · ${k.hiddenConfiguration?'代价与配置保密':k.compose?abilityCostText(k,c.resources||[]):(k.chant?'引导'+k.chant+'动作':k.battleAP+' 战斗AP')+' · '+k.cost+' MP'}${k.onceBattle?' · 每战一次':''}${k.onceDay?' · 每日一次':''}</small><p>${esc(k.desc)}</p>${k.sourceText?`<details class="library-source"><summary>御主技能库原文</summary><pre>${esc(k.sourceText)}</pre></details>`:''}${k.lore?`<p class="muted">渊源：${esc(k.lore)}</p>`:''}${k.originalName?`<small>固定效果来源：${esc(k.originalName)}</small>`:''}${k.libraryKey?`<details class="library-source"><summary>所给技能库原文</summary><pre>${esc(LIBRARY_RULES[k.libraryKey]?.text||'')}</pre></details>`:''}${k.sourceEffects?.length?`<details class="library-source"><summary>Mooncell原始效果方向（FGO）</summary><p>${esc(k.sourceEffects.join('；'))}</p></details>`:''}</section>`).join('')}</div><p class="tiny muted">${c.hiddenVitals?'HP／MP 隐藏':'HP '+c.hp+' · MP '+c.mp} · 普攻 ${c.dice}d4 · 移动 ${c.move} · 射程 ${c.range}。${c.master?'御主固定9点特性。':c.custom?'自建从者固定6点特性，技能可来自效果库或通用建卡引擎。':'本版测试卡，尚待真人平衡。'}</p>`);}
function lobby(){const me=state.players.find(p=>p.id===state.me),host=state.host===me.id,c=playerCard(me);return `<main class="lobby"><div class="page-title"><div><div class="eyebrow">CONTRACT CHAMBER · v0.6.1</div><h1>先选职阶，再选英灵</h1><p class="muted">七个职阶先到先得 · ${CATALOGUE_MANIFEST.read} 张Mooncell从者＋7张原模板 · 每位玩家同时控制自己的御主和从者</p></div><div class="room-invite"><small>邀请御主</small><button data-do="copy">${state.code} ⧉</button></div></div><div class="class-seats">${SERVANTS.map(s=>{const p=state.players.find(p=>p.servant===s.id),pc=playerCard(p);return `<article class="class-seat ${p?.id===me.id?'mine':''}" style="--accent:${s.color}"><div>${icon(s.id)}<b>${s.class}</b><small>${p?(p.ready?'已准备':'已占用'):'空缺'}</small></div><h3>${p?esc(pc?.name||p.cardName||'待选择从者'):s.title}</h3><p>${p?esc(p.name):'先到先得'}</p>${!p?`<button class="secondary full" data-do="select" data-id="${s.id}">占用此职阶</button>`:p.id===me.id?'<button class="text-button" data-do="releaseClass">释放职阶</button>':''}${host?`<label class="spirit-setting">审卡灵格<select class="spirit-select" data-servant="${s.id}">${['E','D','C','B','A','EX'].map(r=>`<option value="${r}" ${r===(p?.spirit||state.spiritOverrides?.[s.id]||s.spirit)?'selected':''}>${r}</option>`).join('')}</select></label>`:''}</article>`;}).join('')}</div><section class="contract-builder panel"><div class="panel-title"><span>我的契约配置</span><small>固定特性预算 · 可创建新技能</small></div><div class="contract-columns"><div><h2>${me.servant?me.servant.toUpperCase():'尚未占用职阶'}</h2><p>${c?esc(c.name):'先选择职阶，再从图鉴中选一位从者，或以库内效果创建新从者。'}</p><div class="builder-actions"><button class="primary" data-do="roster" ${!me.servant?'disabled':''}>选择${me.servant?me.servant.toUpperCase():''}从者</button><button class="secondary" data-do="builder" ${!me.servant?'disabled':''}>自建从者 · 6点</button>${c?`<button class="text-button" data-do="card" data-id="${c.id}">查看选中卡</button>`:''}</div></div><div><h2>御主单位</h2><p>${esc(me.masterDraft?.name||'御主')} · 独立日常／战斗行动 · 9点特性</p><button class="secondary" data-do="masterBuilder">搭配御主技能与特性</button><p class="tiny muted">初始3技能栏；额外栏位按规则用特性点购买。全部效果服务端校验。</p></div></div></section><div class="lobby-bottom"><div><b>${state.players.length}<span> / 7 位御主</span></b><p class="muted">${state.players.filter(p=>p.ready).length} 人准备。所有真人配置完成后房主可用AI补齐其余职阶。</p></div><div class="lobby-buttons"><button class="secondary" data-do="leave">离开</button><button class="${me.ready?'secondary':'primary'}" data-do="ready" ${!c?'disabled':''}>${me.ready?'取消准备':'我已准备'}</button>${host?`<button class="primary" data-do="start" ${state.players.some(p=>!p.ready)?'disabled':''}>${state.players.length<7?'AI补位并开始':'开始战争'} →</button>`:''}</div></div></main>`;}
function unitPanel(u,me,isMine){const c=viewDef(u),own=(u.owner||u.id)===state.me,can=isMine&&own&&u.id===me.id&&u.alive&&!state.pendingAttack;if(!own)return `<div class="panel-title"><span>敌方单位</span></div><div class="selected-servant" style="--accent:${c.color}">${icon(u.kind==='master'?'master':u.servant)}<div><small>${c.class||''}</small><h2>${esc(c.name)}</h2></div></div><p class="hidden-vitals">生命 HP：隐藏<br>魔力 MP：隐藏</p>${statusMarkup(state,u)}<button class="secondary full" data-do="inspect" data-id="${me.id}">返回我的单位</button>`;return `<div class="unit-summary"><div class="panel-title"><span>${u.kind==='master'?'御主单位':'从者单位'}</span><button class="text-button" data-do="card" data-id="${u.id}">完整卡 ↗</button></div><div class="selected-servant" style="--accent:${c.color}">${icon(u.kind==='master'?'master':u.servant)}<div><small>${c.class} · ${esc(c.title||'')}</small><h2>${esc(c.name)}</h2></div></div><div class="stat-line"><span>生命 <b>${stat(u.hp)}<i> / ${u.maxHp}</i></b></span><small>${u.shield?'护盾'+u.shield:''}</small></div>${bar(u.hp,u.maxHp,c.color)}<div class="stat-line"><span>魔力 <b>${stat(u.mp)}<i> / ${c.mp}</i></b></span></div>${bar(u.mp,c.mp,'#799ca7')}<p class="tactical-status">周身 ${bodyRadius(state,u)} 格 · 飞行 ${altitude(u)}/${flightLimit(state,u)} 格</p><div class="resource-row"><span>战斗点 <b>${u.battleAP}</b></span><span>日常点 <b>${stat(u.dailyAP)}</b></span><span>士气 <b>${u.morale}</b></span></div>${statusMarkup(state,u)}</div><div class="unit-controls" data-preserve-scroll="skills">${!own?`<button class="secondary full" data-do="inspect" data-id="${me.id}">返回我的单位</button>`:`<div class="tactical-actions"><button class="secondary" data-do="mode" data-id="backstep" ${!can||!engagedBy(state,u).length||u.battleAP<withdrawalCost(state,u)?'disabled':''}>后撤 · ${withdrawalCost(state,u)} AP</button>${flightLimit(state,u)||altitude(u)?`<button class="secondary" data-do="flightDialog" ${!can||u.battleAP<1?'disabled':''}>飞行高度 · 1 AP</button>`:''}</div><div class="basic-actions"><button data-do="mode" data-id="move" class="${mode==='move'?'chosen':''}" ${!can||u.battleAP<1?'disabled':''}>↗ 移动 <small>1 AP</small></button><button data-do="mode" data-id="attack" class="${mode==='attack'?'chosen':''}" ${!can||u.battleAP<1?'disabled':''}>⚔ 普攻 <small>1 AP</small></button><button data-do="retreat" ${!can||u.battleAP<1?'disabled':''}>↩ 撤退 <small>1 AP</small></button></div><div class="advanced-actions"><button class="secondary compact" data-do="mode" data-id="charge" ${!can||u.battleAP<1?'disabled':''}>冲锋 · 1 AP</button>${u.servant==='lancer'&&u.kind!=='master'?`<button class="secondary compact" data-do="sweep" ${!can||u.battleAP<1?'disabled':''}>横扫 · 1 AP</button>`:''}</div>${u.channel?`<div class="channel-box"><b>${u.channel.ready?'引导完成 · 请选择目标地点':'正在引导 · 还需'+u.channel.remaining+'动作'}</b>${u.channel.ready?`<button class="primary" data-do="aimNP" ${u.id!==me.id||state.pendingAttack||!isMine&&!u.channel.instant?'disabled':''}>选择目标地点 · 0 AP</button>${c.skills.find(k=>k.id===u.channel.skillId)?.shape==='selfArea'?'<button class="primary" data-do="releaseSelfNP">以自身为中心释放</button>':''}`:`<button class="primary" data-do="channel" ${!can||u.battleAP<1?'disabled':''}>继续引导</button>`}<button class="text-button" data-do="cancelChannel">放弃引导／释放</button></div>`:''}<div class="action-label">技能与宝具 <small>原有技能与自建技能</small></div><div class="abilities">${c.skills.filter(k=>!k.passive&&['battle','both'].includes(k.phase)).map(k=>`<button class="ability ${mode===k.id?'chosen':''} ${k.np?'noble':''}" data-do="ability" data-id="${k.id}" ${!can&&!(k.id==='resist'&&state.battle?.participants.includes(u.id))||u.battleAP<(k.chant||k.np&&k.type==='attack'?1:k.battleAP)||availableMana(u)<manaCost(state,k,u)||u.cd[k.id]>0||k.compose&&!canPayAbility(state,u,k)||k.onceBattle&&u.battleUses?.[k.id]||k.onceDay&&u.dayUses?.[k.id]===state.day?'disabled':''}><div><b>${k.np?'<i>宝具</i>':''}${esc(k.name)}</b><span>${esc(k.rank||'')}</span></div><small>${k.rule?'多词条 · 按词条结算':k.compose?abilityCostText(k,c.resources||[],state.day>7?2:1):(k.chant?'引导'+k.chant+'动作':k.battleAP+' AP')+' · '+manaCost(state,k,u)+' MP'}${u.cd[k.id]?' · CD '+u.cd[k.id]:''}</small><p>${esc(k.desc)}</p></button>`).join('')}</div>${u.kind==='master'&&c.traits?.servantHeal?`<button class="secondary full" data-do="healServant" ${!can?'disabled':''}>治愈从者 · 下时间回合回复30 HP</button>`:''}${c.skills.some(k=>k.id==='masterGun')?`<button class="secondary full" data-do="mode" data-id="preciseAttack" ${!can||u.battleAP<2||u.cd.precise>0?'disabled':''}>精准射击 · 2 AP · 通常伤害+4</button>`:''}<div class="seal-row"><span class="command-seals">⟐</span><button class="text-button" data-do="seal">令咒 · 随时使用 ↗</button>${u.kind!=='master'?'<button class="text-button" data-do="supply">御主供魔</button>':''}</div><label class="morale-option"><input type="checkbox" id="autoMorale" ${u.autoMorale?'checked':''}>自动士气应对</label><button class="primary full" data-do="end" ${!can?'disabled':''}>${can?'结束战斗回合 →':'等待其他单位…'}</button>`}<p class="tiny passive-note">${esc(c.passive||'')}</p></div>`;}
function grailPanel(){const cup=state?.grail;if(!cup?.spawned)return '';const holder=state.units.find(u=>u.id===cup.holderId),mine=holder&&(holder.owner||holder.id)===state.me,u=myUnit(),can=dailyReady(state,u);return `<section class="grail-banner"><div><span class="eyebrow">HOLY GRAIL MANIFESTED · 全图公开</span><h2>圣杯 · ${REGION_BY_ID[cup.region]?.name}</h2><p>${holder?esc(viewDef(holder).name)+' 持有，不能移动':'落在地面，可前往拾取'}${cup.ritual?' · 仪式进行中，剩余'+Math.max(0,cup.ritual.completeAt-state.timeIndex)+'次时间推进':''}</p></div><div>${!holder?`<button class="primary" data-do="grailPickup" ${!can||u.region!==cup.region?'disabled':''}>拾起圣杯</button>`:mine?`<button class="secondary" data-do="grailDrop">随时放下圣杯</button><button class="primary" data-do="grailRitual" ${!can||holder.id!==u.id||cup.ritual?'disabled':''}>开始完整时间回合仪式</button>`:'<span>前往同区交战，可打断仪式</span>'}</div></section>`;}
function dailyPlanLabel(unit){const plan=state.dailyPlans?.[unit.id];if(!plan)return state.dailySubmitted?.includes(unit.id)?'本次已跳过。':'请选择本次动作，再切换到另一位契约方。';const skill=viewDef(unit).skills.find(k=>k.id===plan.skill),cost=plan.type==='dailySleep'?3:['skill','masterSkill'].includes(plan.type)?skill?.dailyAP||0:1,label=plan.type==='dailyMove'?'移动至 '+REGION_BY_ID[plan.region].name:plan.type==='dailySleep'?'休眠':plan.type==='dailyEat'?'进食':plan.type==='dailyLey'?'连接灵脉':plan.type==='dailyEnd'?'待机':skill?.name||'已选动作';return `本次预留：${label} · ${cost} 日常点，统一结算时扣除。`;}
function worldMap(){const me=myUnit(),current=activeUnit(state)||me,isMine=dailyReady(state,me),region=REGION_BY_ID[selectedRegion||me.region],c=viewDef(me),neighbors=adjacentRegions(me.region),regionOf=u=>u.region||(state.grail?.holderId===u.id?state.grail.region:null),present=state.units.filter(u=>u.alive&&regionOf(u)===region.id),enemies=state.units.filter(u=>u.alive&&(u.owner||u.id)!==state.me&&regionOf(u)===me.region);const bg=localStorage.getItem('grail-map-image')||'/assets/fuyuki-night.webp';return `<main class="war-room world-screen"><div class="war-title"><div><div class="eyebrow">FUYUKI CITY / NIGHT MAP · v0.6.1</div><h1>冬木市 · 圣杯战线</h1><p class="calendar-inline">${state.phase==='battle'?'区域交战进行中，日常暂停。':'13处地点，以树形道路连接；未发现单位保持隐藏。'}</p></div><div class="war-controls">${state.battle&&!state.battle.spectator?'<button class="primary compact" data-do="battleView">查看战斗 →</button>':''}<button class="secondary compact" data-do="copy">${demo?'本地演习':state.code+' ⧉'}</button><button class="nav-button" data-do="leave">退出</button></div></div>${calendar()}${actorSwitcher()}${grailPanel()}<div class="world-turn-banner"><span><i class="live-dot"></i>${state.phase==='finished'?'战争结束':state.phase==='battle'?'等待区域交战结束':isMine?'同步行动 '+(state.dailyStep+1)+'/3 · 请提交 '+esc(c.name)+' 的行动':'同步行动 '+(state.dailyStep+1)+'/3 · '+(state.dailyConfirmed?.includes(state.me)?'已确认，等待统一结算':dailyCanResolve(state,state.me)?'主从动作已选好，请点击结算':'请切换主从，选择另一位的动作')}</span><span id="countdown">--:--</span></div><div class="world-layout"><section class="illustrated-map-panel panel"><div class="panel-title"><span>冬木夜景 · 13地点</span><div><button class="text-button" data-do="mapImage">更换本机底图</button> · <button class="text-button" data-do="resetMapImage">还原</button></div></div><div class="map-scroll"><div class="illustrated-map" style="background-image:url('${bg}')">${worldRoads()}${REGIONS.map(r=>{const occupants=state.units.filter(u=>u.alive&&regionOf(u)===r.id),cup=state.grail?.spawned&&state.grail.region===r.id;return `<button class="map-location ${r.id===region.id?'selected-region':''} ${r.id===me.region?'my-region':''} ${cup?'grail-location':''}" data-do="region" data-id="${r.id}" style="left:${r.px}%;top:${r.py}%"><span class="location-symbol">${cup?'♜':r.ley?'✧':r.id==='bridge'?'⌁':'◇'}</span><b>${r.name}</b><span class="location-pieces">${occupants.map(u=>`<i class="world-piece ${u.kind==='master'?'master-piece':''}" style="color:${viewDef(u).color}" title="${esc(viewDef(u).name)}">${u.kind==='master'?'御':viewDef(u).symbol||'从'}</i>`).join('')}</span></button>`;}).join('')}</div></div><div class="world-map-footer">树形道路决定可移动区域。底图更换仅保存在本机；单位和圣杯标记始终由引擎绘制。</div><input id="mapImageInput" type="file" accept="image/png,image/jpeg,image/webp" hidden></section><aside class="world-sidebar"><section class="panel world-resource-panel"><div class="panel-title"><span>${me.kind==='master'?'御主':'从者'} · 同步日常行动</span><button class="text-button" data-do="card" data-id="${me.id}">角色卡 ↗</button></div><div class="world-master" style="--accent:${c.color}">${icon(me.kind==='master'?'master':me.servant)}<div><small>${c.class}</small><h2>${esc(c.name)}</h2></div></div><div class="point-wallet"><div><span>日常行动点</span><b>${me.dailyAP}<small> / 3</small></b></div><div><span>战斗行动点</span><b>${me.battleAP}<small> / 2</small></b></div></div><p class="tiny muted daily-plan-preview">${esc(dailyPlanLabel(me))}</p><div class="world-vitals"><span>HP ${me.hp} / ${me.maxHp}</span>${bar(me.hp,me.maxHp,c.color)}<span>MP ${me.mp} / ${c.mp}</span>${bar(me.mp,c.mp,'#799ca7')}</div><div class="daily-library">${c.skills.filter(k=>!k.passive&&['daily','both'].includes(k.phase)).map(k=>`<button class="secondary full" data-do="ability" data-id="${k.id}" ${!isMine||me.dailyAP<(k.dailyAP||0)||availableMana(me)<manaCost(state,k,me)||k.onceDay&&me.dayUses?.[k.id]===state.day||k.onceSlot&&me.slotUses?.[k.id]||k.compose&&!canPayAbility(state,me,k)?'disabled':''}>${esc(k.name)}<small>${k.rule?'多词条 · 按词条结算':k.compose?abilityCostText(k,c.resources||[],state.day>7?2:1):(k.dailyAP||0)+' 日常点 · '+manaCost(state,k,me)+' MP'}</small></button>`).join('')}</div><div class="daily-buttons"><button class="secondary" data-do="dailyEat" ${!isMine||me.dailyAP<1?'disabled':''}>进食 <small>1点 · 1d10</small></button><button class="secondary" data-do="dailySleep" ${!isMine||me.dailyAP<3||state.dailyStep>0?'disabled':''}>休眠 <small>3点 · 4d10</small></button><button class="secondary" data-do="dailyLey" ${!isMine||me.dailyAP<1||!REGION_BY_ID[me.region].ley||state.leyOwners[me.region]?'disabled':''}>连接灵脉 <small>1日常点</small></button><button class="primary" data-do="engage" ${!isMine||me.dailyAP<1||!enemies.length?'disabled':''}>指定已发现敌人交战</button></div>${me.kind==='master'&&c.traits?.servantHeal?`<button class="secondary full" data-do="healServant" ${!isMine?'disabled':''}>治愈从者 · 下回合回复30</button>`:''}${state.units.some(u=>u.owner===state.me&&u.earnedTraits>0)?'<button class="secondary full" data-do="earned">分配获得的通用特性点</button>':''}<div class="world-free-actions"><button class="text-button" data-do="seal">令咒 · 日常亦可用</button>${me.kind!=='master'?'<button class="text-button" data-do="supply">御主供魔</button>':''}</div><button class="primary full" data-do="dailyEnd" ${!isMine?'disabled':''}>${isMine?'选择待机 · 本次消耗 1 点':'本次动作已选／跳过'}</button><button class="primary full daily-resolve" data-do="dailyResolve" ${!dailyCanResolve(state,state.me)?'disabled':''}>${state.dailyConfirmed?.includes(state.me)?'已确认，等待其他玩家…':'结算本次行动（主从同步）'}</button><p class="tiny muted daily-hint">御主和从者各有3日常点，每次各选择一个动作（移动各用1点），再点击结算本次行动。所有玩家确认后统一执行；未结算前显示的是预留动作。可切换单位分别提交；提交后不能追加。发起战斗不扣点，参战替代下一次日常行动并扣1点。圣杯持有者不能移动。</p></section><section class="panel region-details"><div class="panel-title"><span>${region.name}</span><small>${region.ley?'主灵脉':'区域情报'}</small></div><p>${region.desc}</p><div class="region-people">${present.map(u=>`<button data-do="card" data-id="${u.id}">${icon(u.kind==='master'?'master':u.servant)}<span>${esc(viewDef(u).name)}</span><small>${u.kind==='master'?'御主':'从者'} · ${u.owner===state.me?stat(u.hp)+' HP':'生命／魔力隐藏'}</small></button>`).join('')||'<p>未发现其他单位。</p>'}</div><button class="secondary full" data-do="dailyMove" data-id="${region.id}" ${!isMine||me.dailyAP<1||!neighbors.some(n=>n.id===region.id)||state.grail?.holderId===me.id?'disabled':''}>移动到 ${region.name}<small>1 日常点</small></button></section></aside></div>${chronology()}</main>`;}

let archiveMode='cards',archivePage=0,archiveQuery='',archiveClass='all',rosterPicking=false;
function openRoster(){rosterPicking=true;archiveMode='cards';archiveQuery='';archivePage=0;archiveClass=state.players.find(p=>p.id===state.me).servant;openCatalogue();}
function openArchive(){rosterPicking=false;archiveMode='cards';archiveQuery='';archivePage=0;archiveClass='all';openCatalogue();}
function openCatalogue(){openModal(`<div class="eyebrow">CHALDEA RECORDS · MOONCELL</div><h2>${rosterPicking?'选择回应召唤的从者':'英灵档案与效果库'}</h2><p class="muted">369张七职阶可召唤记录（含泳装、Alter、不同灵基）＋7张原模板。技能、宝具为极简杯战棋改编，卡内可追溯原始页面。</p><div class="catalogue-tabs">${[['cards','从者 '+ROSTER.length],['skills','技能 '+SKILL_BANK.length],['nps','宝具 '+NP_BANK.length],['masters','御主技能 '+MASTER_SKILLS.length]].map(([id,label])=>`<button class="${id===archiveMode?'chosen':''}" data-do="archiveTab" data-id="${id}">${label}</button>`).join('')}</div><div class="catalogue-filter"><input id="archiveSearch" placeholder="搜索名称、职阶、效果" value="${esc(archiveQuery)}">${!rosterPicking?`<select id="archiveClass"><option value="all">全部职阶</option>${CLASS_IDS.map(c=>`<option ${c===archiveClass?'selected':''} value="${c}">${c.toUpperCase()}</option>`).join('')}</select>`:''}</div><div id="catalogueResults"></div>`);renderCatalogue();}
function renderCatalogue(){const bank=archiveMode==='cards'?ROSTER:archiveMode==='skills'?SKILL_BANK:archiveMode==='nps'?NP_BANK:MASTER_SKILLS;const list=bank.filter(k=>(archiveMode!=='cards'||archiveClass==='all'||k.classId===archiveClass)&&(`${k.name} ${k.class||''} ${k.desc||''} ${k.bio||''}`).toLowerCase().includes(archiveQuery.toLowerCase()));const pages=Math.max(1,Math.ceil(list.length/24));archivePage=Math.min(archivePage,pages-1);$('#catalogueResults').innerHTML=`<div class="catalogue-meta">共 ${list.length} 条 · 第 ${archivePage+1} / ${pages} 页</div><div class="catalogue-cards">${list.slice(archivePage*24,(archivePage+1)*24).map(k=>archiveMode==='cards'?`<article class="catalogue-card" style="--accent:${k.color}"><span>${k.class} · ${k.spirit}灵格</span><h3>${esc(k.name)}</h3><p>${esc(k.bio)}</p><div><button class="text-button" data-do="card" data-id="${k.id}">卡片详情 ↗</button>${rosterPicking?`<button class="primary compact" data-do="pickCard" data-id="${k.id}">选用</button>`:''}</div></article>`:`<article class="catalogue-card"><span>${esc(k.rank)} · ${k.battleAP||0} 战斗AP · ${k.cost||0} MP</span><h3>${esc(k.name)}</h3><p>${esc(k.desc)}</p><small>条目编号：${esc(k.bankId||k.id)}</small>${k.sourceText?`<details><summary>所给御主技能库原文</summary><pre>${esc(k.sourceText)}</pre></details>`:''}${k.sourceLink?`<a class="text-button" href="${esc(k.sourceLink)}" target="_blank" rel="noopener">Mooncell来源 ↗</a>`:''}${k.libraryKey?`<details><summary>技能库原文</summary><pre>${esc(LIBRARY_RULES[k.libraryKey]?.text||'')}</pre></details>`:''}</article>`).join('')}</div><div class="catalogue-pagination"><button class="secondary" data-do="archivePage" data-id="${archivePage-1}" ${archivePage===0?'disabled':''}>← 上一页</button><span>${archivePage+1} / ${pages}</span><button class="secondary" data-do="archivePage" data-id="${archivePage+1}" ${archivePage===pages-1?'disabled':''}>下一页 →</button></div>`;}
function builderTraits(kind,traits){return `<div class="trait-grid">${TRAITS.filter(t=>t.scope==='general'||t.scope===kind).map(t=>`<label><span>${t.name} <small>${traitPrice(t.id,kind,state?.players.find(p=>p.id===state.me)?.servant||'')}点／层</small></span><input type="number" class="trait-value" data-id="${t.id}" min="0" max="${t.max}" value="${traits[t.id]||0}"><small>${t.desc}</small></label>`).join('')}</div>`;}
function effectRows(kind,items,count){const bank=kind==='skills'?SKILL_BY_BANK:NP_BY_BANK;return Array.from({length:count},(_,i)=>{const v=items[i]||{},k=bank[v.bankId];return `<div class="effect-row" data-kind="${kind}"><input class="effect-choice" list="bank-${kind}" placeholder="搜索名称或效果关键词" value="${esc(v.bankId||'')}"><input class="effect-name" maxlength="60" placeholder="自定义技能名称（可空）" value="${esc(v.name||'')}"><input class="effect-lore" maxlength="500" placeholder="渊源（可空）" value="${esc(v.lore||'')}"><small class="effect-preview">${esc(k?.desc||'留空表示不使用该栏；效果固定，不接受自编数值。')}</small></div>`;}).join('');}
function servantRankFields(player,draft){const grades=['E','D','C','B','A','EX'],select=(label,attributes,value)=>`<label>${label}<select ${attributes}>${grades.map(r=>`<option value="${r}" ${r===String(value||'B').replace(/[+＋\-－]/g,'')?'selected':''}>${r}</option>`).join('')}</select></label>`;return `<section class="servant-rank-editor"><h3>从者属性与灵格</h3><div class="composer-grid">${['筋力','耐久','敏捷','魔力','幸运'].map((name,i)=>select(name+'等级',`data-servant-rank="${i}"`,(draft.ranks||BY_ID[player.servant].ranks)[i])).join('')}${select('整体灵格','id="builderSpirit"',draft.spirit||player.spirit||'B')}</div><p class="tiny muted">属性会按现有换算更新HP、MP、移动、攻击骰数和幸运。${state.spiritConfigured?.[player.servant]?'本职阶已有房主灵格审定，开局以房主审定为准。':''}</p><h3>职阶技能等级</h3><div class="composer-grid">${classPackage(player.servant,[],draft.classSkillRanks||{}).map(k=>select(k.name,`data-class-skill-rank="${esc(k.libraryKey)}"`,k.rank)).join('')}</div></section>`;}
function openBuilder(kind){const p=state.players.find(p=>p.id===state.me),master=kind==='master',draft=master?p.masterDraft||DEFAULT_MASTER:p.customCard||{name:'',bio:'',traits:{},skills:[],nps:[]};openModal(`<div class="eyebrow">${master?'MASTER · 9':'SERVANT · 6'} FIXED TRAIT POINTS</div><h2>${master?'御主契约卡':'创建 '+p.servant.toUpperCase()+' 从者'}</h2><p class="muted">所有房间固定规则书预算。名称、简介、渊源仅填写虚构资料，请勿输入真实住址。可使用旧技能或创建新技能；代价、资源与效果会由服务器逐项校验。</p><div id="builderForm" data-kind="${kind}"><label>人物名称<input id="builderName" maxlength="60" value="${esc(draft.name)}"></label><label>人物简介<textarea id="builderBio" maxlength="1500">${esc(draft.bio||'')}</textarea></label>${master?'':servantRankFields(p,draft)}${cardComposerMarkup(draft,kind)}${master?`<label>基础属性组<select id="masterArchetype">${[['magus','魔术师 E/D/D/C/D'],['fighter','格斗者 C/C/C/E/D'],['sniper','射手 D/D/C/D/C']].map(([id,label])=>`<option value="${id}" ${id===draft.archetype?'selected':''}>${label}</option>`).join('')}</select></label><p class="tiny muted">基础属性组为网页建卡模板；特性与同名技能使用所给数据库。</p>`:''}<h3>分配特性</h3><div id="budgetReadout" aria-live="polite"></div>${builderTraits(kind,draft.traits||{})}${master?`<h3>御主技能 · 初始3栏</h3><div class="master-skill-choices">${MASTER_SKILLS.map(k=>`<label><input type="checkbox" class="master-skill-check" value="${k.id}" ${draft.skills.includes(k.id)?'checked':''}><span><b>${k.name} ${k.rank}</b><small>${k.desc}</small></span></label>`).join('')}</div>`:`<h3>固有技能 · 初始3栏</h3><p class="tiny muted">最多显示6栏；超过3栏须先用特性点购买。职阶被动另行附加。</p>${effectRows('skills',draft.skills||[],6)}<h3>宝具 · 初始1栏</h3>${effectRows('nps',draft.nps||[],3)}`}</div><div id="characterLivePreview" class="character-live-preview" aria-live="polite"></div><p id="builderSaveFeedback" role="status" aria-live="polite"></p><button class="primary full" data-do="saveBuilder" data-kind="${kind}">校验固定预算并保存角色卡 →</button>`);mountCardComposer($('#builderForm'),updateBudget);const stopSearch=mountEditorSearch($('#builderForm'),{banks:{skills:SKILL_BANK,nps:NP_BANK}});modal.addEventListener('close',stopSearch,{once:true});updateBudget();}
function readBuilder(){const kind=$('#builderForm').dataset.kind,traits=Object.fromEntries([...document.querySelectorAll('.trait-value')].map(i=>[i.dataset.id,Number(i.value)]).filter(([,n])=>n!==0)),draft={name:$('#builderName').value,bio:$('#builderBio').value,traits,...readCardComposer($('#builderForm'))};if(kind==='master'){draft.archetype=$('#masterArchetype').value;draft.skills=[...document.querySelectorAll('.master-skill-check:checked')].map(i=>i.value);}else{draft.ranks=[...document.querySelectorAll('[data-servant-rank]')].map(select=>select.value);draft.spirit=$('#builderSpirit').value;draft.classSkillRanks=Object.fromEntries([...document.querySelectorAll('[data-class-skill-rank]')].map(select=>[select.dataset.classSkillRank,select.value]));for(const k of ['skills','nps'])draft[k]=[...document.querySelectorAll(`.effect-row[data-kind="${k}"]`)].map(row=>({bankId:row.querySelector('.effect-choice').value.trim(),name:row.querySelector('.effect-name').value,lore:row.querySelector('.effect-lore').value})).filter(v=>v.bankId);}return {kind,draft};}
function updateBudget(){if(!$('#builderForm'))return;try{const {kind,draft}=readBuilder(),a=traitAudit(draft.traits,kind,state.players.find(p=>p.id===state.me)?.servant||'');const newSkills=(draft.abilities||[]).filter(a=>a.category!=='noble_phantasm').length,newNP=(draft.abilities||[]).filter(a=>a.category==='noble_phantasm').length,skillCount=(draft.skills||[]).length+newSkills,npCount=(draft.nps||[]).length+newNP;if(skillCount>3+(draft.traits?.[kind==='master'?'masterSlot':'extraSkill']||0)||kind!=='master'&&npCount>1+(draft.traits?.extraNP||0))throw Error('新建技能与旧技能合计超过可用栏位，请减少选用或购买额外栏位。');$('#budgetReadout').textContent=`技能${skillCount}项${kind==='master'?'':' · 宝具'+npCount+'项'} · 专属预算${a.budget}点（可换通用） · 已用${a.spent}点${a.bonus?'（战斗专家额外通用点'+a.bonus+'）':''} · 剩余${a.remaining}点`;$('#budgetReadout').className='budget-ok';const preview=$('#characterLivePreview');if(preview){try{const card=kind==='master'?createMasterCard(draft):createCustomServant(draft,state.players.find(p=>p.id===state.me).servant);preview.innerHTML=`<b>${esc(card.name)} · 人物预览</b><span>HP ${card.hp}</span><span>MP ${card.mp}</span><span>移动 ${card.move}</span>${kind==='master'?'':`<span>灵格 ${card.spirit}</span><span>属性 ${card.ranks.join(' / ')}</span>`}<span>技能 ${skillCount} 项${kind==='master'?'':' · 宝具 '+npCount+' 项'}</span>`;}catch(error){preview.textContent='人物预览：'+error.message;}}}catch(e){$('#budgetReadout').textContent=e.message;$('#budgetReadout').className='budget-error';const preview=$('#characterLivePreview');if(preview)preview.textContent='请先处理上方配置提示。';}}
async function saveBuilder(kind){try{const {draft}=readBuilder(),p=state.players.find(p=>p.id===state.me);if(kind==='master')createMasterCard(draft);else createCustomServant(draft,p.servant);const button=modal.querySelector('[data-do=saveBuilder]'),feedback=$('#builderSaveFeedback');button.disabled=true;feedback.className='';feedback.textContent='正在保存…';try{const saved=await send({type:kind==='master'?'masterCard':'customCard',draft},'lobby');if(saved)modal.close();else feedback.textContent='保存未完成，填写内容已保留，请重试。';}finally{button.disabled=false;}}catch(e){const feedback=$('#builderSaveFeedback');if(feedback){feedback.textContent=e.message;feedback.className='budget-error';}toast(e.message);}}
const SEAL_OPTIONS=[['attack','仅从者 · 本场全部攻击 +15','1划'],['defense','仅从者 · 本场全部防御 +15','1划'],['heal','从者回复60生命','1划'],['mana','从者回复60魔力','1划'],['manaMaster','御主回复60魔力','1划'],['defend','从者本轮应对必定成功','1划'],['unavoidable','从者本轮攻击无法被应对','1划'],['compel','命令从者执行一项指令','1–3划'],['teleport','传送从者至御主视野内','1划'],['escape','主从一起传送脱战','2划'],['release','缩短宝具引导，每划4动作','1–3划']];
function openSealDialog(){const mine=state.units.filter(u=>(u.owner||u.id)===state.me),s=mine.find(u=>u.kind==='servant'),m=mine.find(u=>u.kind==='master');openModal(`<div class="eyebrow">COMMAND SPELL · ANY TIME</div><h2>以令咒之名 · 剩余${s?.seals||0}划</h2><p class="muted">日常与战斗都可使用，不消耗行动点。应对必成与无法应对相互抵消。御主濒死时依规则作敏捷检定，并自动执行最后指令预案。</p><div class="seal-options">${SEAL_OPTIONS.map(([id,label,cost])=>`<button class="secondary" data-do="sealChoice" data-id="${id}" ${!m?.alive||!s?.alive||!s.seals?'disabled':''}>${label}<small>${cost}</small></button>`).join('')}</div>`);}
function chooseSeal(id){const m=state.units.find(u=>u.kind==='master'&&u.owner===state.me),s=state.units.find(u=>u.kind==='servant'&&u.owner===state.me),o=SEAL_OPTIONS.find(o=>o[0]===id);let fields='';if(['teleport','escape'].includes(id)){fields=`<label>目的区域<select id="sealRegion">${[REGION_BY_ID[m.region],...adjacentRegions(m.region)].map(r=>`<option value="${r.id}">${r.name}</option>`).join('')}</select></label>`;if(id==='teleport'&&state.phase==='battle')fields+=`<label>战斗格（留空则区域传送）<input id="sealCell" placeholder="例如 A1，须在御主视线内"></label>`;}if(['compel','release'].includes(id))fields+=`<label>消耗划数<input id="sealCount" type="number" min="1" max="${Math.min(3,s.seals)}" value="1"></label>`;if(id==='compel')fields+='<label>具体命令<input id="sealCommand" maxlength="160" placeholder="输入从者应服从的指令"></label>';openModal(`<div class="eyebrow">COMMAND SPELL</div><h2>${o[1]}</h2><p>消耗${o[2]}。回复受上限约束；圣杯持有者不能传送。</p>${fields}<button class="primary" data-do="confirmSeal" data-id="${id}">执行令咒 →</button>`);}
function confirmSeal(id){const data={type:'seal',choice:id};if($('#sealRegion'))data.region=$('#sealRegion').value;if($('#sealCount'))data.count=+$('#sealCount').value;if($('#sealCommand'))data.command=$('#sealCommand').value;if($('#sealCell')?.value.trim()){const cell=$('#sealCell').value.trim().toUpperCase().match(/^([A-T])(\d{1,2})$/);if(!cell){toast('战斗格格式应为A1至T20。');return;}data.x=cell[1].charCodeAt(0)-65;data.y=+cell[2]-1;}modal.close();send(data);}
document.addEventListener('input',e=>{if(e.target.id==='archiveSearch'){archiveQuery=e.target.value;archivePage=0;renderCatalogue();}if(e.target.closest('#builderForm')){if(e.target.classList.contains('effect-choice')){const row=e.target.closest('.effect-row'),bank=row.dataset.kind==='skills'?SKILL_BY_BANK:NP_BY_BANK;row.querySelector('.effect-preview').textContent=bank[e.target.value]?.desc||(e.target.value?'请从搜索列表中选择已有技能。':'此栏未选用');}updateBudget();}});
document.addEventListener('change',async e=>{if(e.target.closest('#builderForm'))updateBudget();if(e.target.id==='archiveClass'){archiveClass=e.target.value;archivePage=0;renderCatalogue();}if(e.target.id==='mapImageInput'){const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>4*1024*1024){toast('请选择4MB以内的PNG、JPG或WebP图片。');return;}try{const url=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(file);});localStorage.setItem('grail-map-image',url);render();toast('底图已保存在本机。');}catch{toast('图片保存失败，请换一张较小图片。');}}});
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;if(b.dataset.do==='archiveTab'){archiveMode=b.dataset.id;archivePage=0;openCatalogue();}if(b.dataset.do==='archivePage'){archivePage=+b.dataset.id;renderCatalogue();$('#catalogueResults').scrollIntoView({block:'start'});}});

function openMasterSkill(k){const u=myUnit();openModal(`<h2>${esc(k.name)}</h2><p>${esc(k.desc)}</p>${k.id==='masterRestart'?`<label>缩短哪个技能的冷却<select id="restartSkill">${Object.entries(u.cd).filter(([id,n])=>n>0).map(([id,n])=>`<option value="${id}">${esc(viewDef(u).skills.find(k=>k.id===id)?.name||id)} · ${n}轮</option>`).join('')}</select></label>`:''}${k.id==='masterEmergency'?'<label>立即恢复<select id="emergencyResource"><option value="hp">12生命</option><option value="mp">12魔力</option></select></label>':''}<button class="primary" data-do="confirmMasterSkill" data-id="${k.id}">确认使用</button>`);}
function openEarned(){const m=state.units.find(u=>u.owner===state.me&&u.kind==='master');openModal(`<h2>分配获得的通用特性 · ${m.earnedTraits}点</h2><p>这是游戏过程中依技能获得的通用点；开局6／9点预算固定。</p><label>授予单位<select id="earnedTarget">${state.units.filter(u=>u.owner===state.me&&u.alive).map(u=>`<option value="${u.id}">${esc(viewDef(u).name)}</option>`).join('')}</select></label><label>通用特性<select id="earnedTrait">${TRAITS.filter(t=>t.scope==='general').map(t=>`<option value="${t.id}">${t.name} · ${t.cost}点</option>`).join('')}</select></label><label>层数<input id="earnedCount" type="number" min="1" max="${m.earnedTraits}" value="1"></label><button class="primary" data-do="confirmEarned">确认分配</button>`);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;if(b.dataset.do==='aid')send({type:'aid',actorId:b.dataset.id});if(b.dataset.do==='earned')openEarned();if(b.dataset.do==='confirmEarned'){const data={type:'allocateEarned',target:$('#earnedTarget').value,trait:$('#earnedTrait').value,count:+$('#earnedCount').value};modal.close();send(data);}});

function localLobby(a){const g=localGame,p=g.players[0];if(a.type==='priorityConfig'){g.priorityTable=normalizePriorityTable(a.priorityTable);g.revision++;return;}if(g.phase!=='lobby')throw Error('战争已经开始。');if(a.type==='claim'){if(!CLASS_IDS.includes(a.servant))throw Error('无效职阶。');p.servant=a.servant;p.cardId=null;p.customCard=null;p.ready=false;}else if(a.type==='releaseClass'){p.servant=null;p.cardId=null;p.customCard=null;p.ready=false;}else if(a.type==='card'){const c=CARD_BY_ID[a.cardId];if(!c||c.classId!==p.servant)throw Error('从者职阶不符。');p.cardId=c.id;p.customCard=null;p.spirit=c.spirit;p.ready=false;}else if(a.type==='customCard'){const approved=createCustomServant(a.draft,p.servant);p.spirit=g.spiritConfigured?.[p.servant]?g.spiritOverrides[p.servant]:approved.spirit;p.customCard=structuredClone(a.draft);p.cardId=null;p.ready=false;}else if(a.type==='masterCard'){createMasterCard(a.draft);p.masterDraft=structuredClone(a.draft);p.ready=false;}else if(a.type==='spirit'){g.spiritConfigured??={};g.spiritConfigured[a.servant]=true;g.spiritOverrides[a.servant]=a.spirit;if(p.servant===a.servant)p.spirit=a.spirit;p.ready=false;}else if(a.type==='ready'){if(a.ready&&(!p.servant||!p.cardId&&!p.customCard))throw Error('请先选择职阶和从者。');p.ready=a.ready;}else if(a.type==='start')startGame(g,true);else throw Error('无效大厅操作。');g.revision++;}

document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;if(b.dataset.do==='respondMorale')submitResponse({useMorale:b.dataset.id==='yes'});if(b.dataset.do==='flightDialog'){const u=myUnit();openModal(`<h2>飞行高度</h2><p>花费1战斗AP；飞行忽略周身与地形阻挡。攻击距离＝平面格距＋高度差，棋子不能重叠。</p><input id="flightHeight" type="number" min="0" max="${flightLimit(state,u)}" value="${altitude(u)}"><button class="primary" data-do="confirmFlight">调整高度</button>`);}if(b.dataset.do==='confirmFlight'){const height=+$('#flightHeight').value;modal.close();send({type:'flight',height});}});
let seenFxBattle=null,seenFxId=0;
function playBattleFX(){if(!state?.battle||state.battle.spectator)return;const bid=state.code+':'+state.battle.id;if(seenFxBattle!==bid){seenFxBattle=bid;seenFxId=Math.max(0,...(state.fx||[]).filter(f=>Date.now()-f.at>2500).map(f=>f.id));}const fresh=(state.fx||[]).filter(f=>f.battleId===state.battle.id&&f.id>seenFxId);if(!fresh.length)return;seenFxId=Math.max(...fresh.map(f=>f.id));const fx=fresh.at(-1);if(Date.now()-fx.at>15000||!document.querySelector('.map'))return;const layer=document.createElement('div');layer.className='combat-cinema '+(fx.np?'phantasm':'skill-fx')+' fx-'+fx.style;layer.setAttribute('aria-hidden','true');const target=fx.targets[0]||fx;const x1=(fx.x+.5)*5,y1=(fx.y+.5)*5,x2=(target.x+.5)*5,y2=(target.y+.5)*5;layer.innerHTML=`<div class="cinema-vignette"></div><div class="cinema-title"><small>${fx.np?'N O B L E   P H A N T A S M':'S K I L L   A C T I V A T E'}</small><strong>${esc(fx.name)}</strong></div><svg viewBox="0 0 100 100" preserveAspectRatio="none"><defs><radialGradient id="impact-${fx.id}"><stop stop-color="#fff"/><stop offset=".2" stop-color="var(--fx-color)"/><stop offset="1" stop-color="var(--fx-color)" stop-opacity="0"/></radialGradient></defs>${Array.from({length:fx.np?13:4},(_,i)=>`<line class="fx-ray" style="--delay:${i*30}ms" x1="${x1+(i-6)*.4}" y1="${y1}" x2="${x2+(i-6)*.5}" y2="${y2}"/>`).join('')}<circle class="fx-impact" cx="${x2}" cy="${y2}" r="18" fill="url(#impact-${fx.id})"/><circle class="fx-ring" cx="${x2}" cy="${y2}" r="11"/>${Array.from({length:20},(_,i)=>`<circle class="fx-spark" style="--delay:${i*24}ms" cx="${x2+Math.cos(i*2.4)*i*.8}" cy="${y2+Math.sin(i*2.4)*i*.8}" r=".3"/>`).join('')}</svg>`;document.querySelector('.map').append(layer);setTimeout(()=>layer.remove(),fx.np?2000:850);}

function counterChoices(u){const choices=counterOptions(state,u.id);if(!choices.length)return '';return `<details class="counter-options"><summary>放弃属性应对，改为反击 · 0AP／1士气</summary><p>双方比较攻击伤害，只有较低方承受差值；不再进行属性应对、士气改判或连锁反击。技能仍支付MP，宝具反击用令咒立即释放。</p><div>${choices.map(k=>`<button class="secondary" data-do="counterDialog" data-id="${k.id}" ${k.enabled?'':'disabled'}><b>${esc(k.name)}</b><small>${k.cost}MP${k.seals?' · '+k.seals+'划令咒':''}${k.reason?' · '+k.reason:''}</small></button>`).join('')}</div></details>`;}
document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;if(b.dataset.do==='counterDialog'){const u=decisionUnit(state),k=counterOptions(state,u.id).find(k=>k.id===b.dataset.id);if(!k)return;openModal(`<h2>反击 · ${esc(k.name)}</h2><p>消耗1士气、${k.cost}MP${k.seals?'、'+k.seals+'划令咒':''}，不消耗行动点。放弃本次属性应对，以双方伤害差值结算；不能再用士气改判或再次反击。</p><button class="primary" data-do="confirmCounter" data-id="${k.id}" data-actor="${u.id}">确认反击</button>`);}if(b.dataset.do==='confirmCounter'){modal.close();send({type:'counter',skill:b.dataset.id,actorId:b.dataset.actor});}});

let seenContestIds=new Set();
function diceHistoryPanel(){const history=(state.contestHistory||[]).filter(r=>r.battleId===state.battle?.id),latest=history.at(-1)?.attackId,rolls=history.filter(r=>r.attackId===latest).slice(-2);if(!rolls.length)return '';return `<section class="private-dice-record"><b>我的最近两次属性对抗 · 敌方骰子保密</b>${rolls.map(r=>`<div><span>${['筋力','耐久','敏捷','魔力','幸运'][r.index]} · ${r.ownRole}</span><strong>${(r.ownDice||[]).join(' + ')} ＋修正${r.ownBonus>=0?'+':''}${r.ownBonus} ＝ ${r.ownTotal}</strong><em>${r.ownSuccess?'对抗成功':'对抗失败'}</em></div>`).join('')}</section>`;}
function playContestDice(){const fresh=(state?.contestHistory||[]).filter(r=>!seenContestIds.has(state.code+':'+r.id));for(const r of fresh)seenContestIds.add(state.code+':'+r.id);const r=fresh.at(-1);if(!r||Date.now()-r.at>12000||!r.ownDice?.length)return;document.querySelector('.dice-cinema')?.remove();const box=document.createElement('section');box.className='dice-cinema rolling';box.setAttribute('aria-live','polite');box.innerHTML=`<b>${['筋力','耐久','敏捷','魔力','幸运'][r.index]}对抗 · 我的${r.ownRole}骰子</b><div class="dice-tray">${r.ownDice.map(()=>'<span class="die">⚄</span>').join('')}</div><div class="opponent-dice">对方骰子：数量和点数均保密</div><p class="dice-verdict">正在掷骰…</p>`;document.body.append(box);const reduced=matchMedia('(prefers-reduced-motion: reduce)').matches;let frame=0;const timer=setInterval(()=>{box.querySelectorAll('.die').forEach((die,i)=>die.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][(frame+i)%6]);frame++;},70);setTimeout(()=>{clearInterval(timer);box.classList.remove('rolling');box.querySelectorAll('.die').forEach((die,i)=>{die.textContent=['⚀','⚁','⚂','⚃','⚄','⚅'][r.ownDice[i]-1];die.title=String(r.ownDice[i]);});box.querySelector('.dice-verdict').textContent=`${r.ownDice.join('+')} ＋修正(${r.ownBonus}) ＝ ${r.ownTotal} · ${r.ownSuccess?'对抗成功':'对抗失败'}`;},reduced?0:850);setTimeout(()=>box.remove(),reduced?3000:4500);}

document.addEventListener('click',e=>{const b=e.target.closest('[data-do]');if(!b||b.disabled)return;if(b.dataset.do==='aimNP'){const k=viewDef(myUnit()).skills.find(k=>k.id===myUnit().channel?.skillId);if(k?.shape==='selfArea'){send({type:'releaseNP'});return;}cancelBattleAim(false);mode='releaseNP';inspected=myUnit().id;render();toast('点击合法目标格释放；选点不再扣AP。');}if(b.dataset.do==='releaseSelfNP')send({type:'releaseNP'});});


function cancelBattleAim(refresh=true){mode=null;controlTarget=null;controlCommand=null;if(refresh)render();}
function selectBattleActor(id){const u=state?.units.find(u=>u.id===id&&(u.owner||u.id)===state.me);if(!u)return;cancelBattleAim(false);actorSelection=id;inspected=null;render();}
async function activateBattleSkill(id){
 const u=myUnit(),k=viewDef(u)?.skills.find(k=>k.id===id);if(!k)return;if(k.rule){openRuleClauses(k);return;}
 cancelBattleAim(false);inspected=u.id;
 const plan=skillPlan(k);
 if(plan==='existing'){
  if(k.type==='master'){
   if(['masterRestart','masterEmergency'].includes(k.id)){render();openMasterSkill(k);return;}
   await send({type:'masterSkill',skill:k.id});return;
  }
  if(k.libraryKey==='pollution'||['burst','charisma'].includes(k.id)){render();libraryDialog(k);return;}
  await send({type:'skill',skill:k.id});return;
 }
 if(plan==='channel'||plan==='immediate'){await send({type:'skill',skill:k.id});return;}
 mode=k.id;render();
}
async function clickBattleCell(x,y){
 if(!state||state.phase!=='battle')return;
 const me=myUnit(),model=createBoardModel(state,me,mode,{target:controlTarget,command:controlCommand}),unit=model.positions.get(`${x},${y}`);
 // Ordinary selection/movement keeps party cards and board selection in sync.
 if(unit&&(unit.owner||unit.id)===state.me&&(!mode||['move','backstep','charge'].includes(mode))){selectBattleActor(unit.id);return;}
 if(state.pendingAttack){if(unit){inspected=unit.id;render();}else toast('请先完成当前攻击的应对。');return;}
 const point={x,y},selection=model.selectionAt(point);
 if(!mode&&unit){inspected=unit.id;render();return;}
 if(!selection.valid){toast(selection.reason||'该格不是合法目标。');return;}
 if(mode==='sacrifice'&&controlCommand&&!controlTarget){controlTarget=unit.id;render();toast('步骤2/2：选择受控单位的动作目的格或攻击目标。');return;}
 const request=mode==='releaseNP'?{type:'releaseNP',x,y}:mode==='sacrifice'&&controlCommand?{type:'skill',skill:mode,target:controlTarget,command:controlCommand,x,y}:['move','backstep','charge','attack','preciseAttack','sweep'].includes(model.effectiveMode)?{type:model.effectiveMode,x,y}:{type:'skill',skill:mode,x,y};
 inspected=me.id;const actor=me.id,success=await send({...request,actorId:actor});if(success){cancelBattleAim(false);render();}
}
document.addEventListener('keydown',event=>{if(event.key==='Escape'&&mode&&!modal.open){event.preventDefault();cancelBattleAim();}});
app.addEventListener('contextmenu',event=>{if(event.target.closest('.sheet-board')&&mode){event.preventDefault();cancelBattleAim();}});

function defenseChoices(u){if(!canUseDefense(state,u))return '';const skills=viewDef(u).skills.filter(k=>k.compose?.trigger==='reaction');if(!skills.length)return '';return `<div class="independent-defenses"><h3>独立防御反应</h3>${skills.map(k=>`<button class="secondary full" data-do="useDefense" data-id="${k.id}" data-actor="${u.id}" ${state.pendingAttack.defensesUsed?.includes(k.id)||u.cd[k.id]>0||!canPayAbility(state,u,k)?'disabled':''}><b>${esc(k.name)}</b><small>${esc(abilityCostText(k,u.card.resources||[],state.day>7?2:1))||'无资源代价'} · ${esc(k.desc)}</small></button>`).join('')}</div>`;}
function priorityRow(key='',value=''){return `<div class="priority-row"><input class="priority-key" placeholder="优先级键，例如 link.protector" maxlength="64" value="${esc(key)}"><input class="priority-value" type="number" min="0" max="10000" placeholder="优先级" value="${value}"><button class="text-button" data-do="priorityRemove">删除</button></div>`;}
function openPriorityDialog(){const entries=Object.entries(state.priorityTable||{});openModal(`<h2>规则优先级</h2><p class="muted">由房主明确配置，数值越大越先处理。不同链接同时生效时须使用不同键和数值；配置缺失时会阻止争议结算，不会随机决定。</p><div id="priorityRows">${entries.length?entries.map(([k,v])=>priorityRow(k,v)).join(''):priorityRow()}</div><button class="secondary" data-do="priorityAdd">添加规则</button><button class="primary" data-do="prioritySave">保存配置</button>`);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-do]');if(!b||b.disabled)return;switch(b.dataset.do){case 'useDefense':await send({type:'useDefense',skill:b.dataset.id,actorId:b.dataset.actor});break;case 'priorityOpen':openPriorityDialog();break;case 'priorityAdd':$('#priorityRows').insertAdjacentHTML('beforeend',priorityRow());break;case 'priorityRemove':b.closest('.priority-row').remove();break;case 'prioritySave':try{const input=Object.create(null);for(const row of document.querySelectorAll('.priority-row')){const key=row.querySelector('.priority-key').value.trim(),value=row.querySelector('.priority-value').value;if(!key&&!value)continue;if(!key||value===''||Object.hasOwn(input,key))throw Error('请填写完整且不重复的优先级键。');input[key]=Number(value);}const priorityTable=normalizePriorityTable(input);if(await send({type:'priorityConfig',priorityTable},'lobby'))modal.close();}catch(error){toast(error.message);}break;}});

function protectionChoices(u){if(state.pendingAttack?.target!==u.id)return '';return [['guards','protectionChoice','优先使用的无敌'],['revivals','revivalChoice','致死时优先使用的复活']].map(([group,id,label])=>{const items=activeCombatEffects(state,u,group).filter(e=>group!=='guards'||e.kind==='invincibility');return items.length>1?`<label>${label}<select id="${id}"><option value="">默认获得顺序</option>${items.map(e=>`<option value="${e.id}">${esc(e.name)} · ${e.charges??'持续'}</option>`).join('')}</select></label>`:'';}).join('');}

function openRuleClauses(k){const u=myUnit();openModal(`<h2>${esc(k.name)} · 独立词条</h2><div class="rule-clause-list">${k.rule.clauses.map(c=>`<section><h3>${esc(c.id)}</h3><p>${esc(c.window)} · ${esc(c.trigger.event)} · ${esc(c.status)}</p><p>${esc((c.costs||[]).map(cost=>cost.resource+'：'+cost.amount).join('；'))}</p>${c.issues?.length?`<p>${esc(c.issues.join('；'))}</p>`:''}${c.targeting.kind!=='self'?`<select data-rule-target="${c.id}">${battleUnits(state).filter(t=>t.alive&&(c.targeting.kind==='ally'?t.owner===u.owner:t.owner!==u.owner)).map(t=>`<option value="${t.id}">${esc(viewDef(t).name)}</option>`).join('')}</select>`:''}<button class="primary compact" data-do="activateClause" data-skill="${k.id}" data-clause="${c.id}" ${c.status!=='implemented'||c.window!=='own_turn'||c.trigger.event!=='manual'?'disabled':''}>发动此词条</button></section>`).join('')}</div>`);}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-do="activateClause"]');if(!b||b.disabled)return;const select=[...document.querySelectorAll('[data-rule-target]')].find(el=>el.dataset.ruleTarget===b.dataset.clause),success=await send({type:'ruleClause',skill:b.dataset.skill,clause:b.dataset.clause,...(select?{target:select.value}:{})});if(success)modal.close();});
